using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    // All k-window sums are equal iff a[i] == a[i + k]: each index class mod k must be constant.
    long long answer = 0;
    vector<long long> group;
    for (int start = 0; start < min(k, n); start++) {
        group.clear();
        for (int i = start; i < n; i += k) group.push_back(a[i]);
        sort(group.begin(), group.end());
        if (group.front() == group.back()) continue;  // already constant: no change
        // Otherwise the class becomes one positive value: keep its most frequent positive value.
        int bestPositive = 0;
        for (size_t s = 0; s < group.size();) {
            size_t e = s;
            while (e < group.size() && group[e] == group[s]) e++;
            if (group[s] > 0) bestPositive = max(bestPositive, (int)(e - s));
            s = e;
        }
        answer += (long long)group.size() - bestPositive;
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // All k-window sums are equal iff a[i] == a[i + k]: each index class mod k must be constant.
        long answer = 0;
        for (int start = 0; start < Math.min(k, n); start++) {
            long[] group = new long[(n - start + k - 1) / k];
            for (int i = start, j = 0; i < n; i += k) group[j++] = a[i];
            Arrays.sort(group);
            int m = group.length;
            if (group[0] == group[m - 1]) continue;  // already constant: no change
            // Otherwise the class becomes one positive value: keep its most frequent positive value.
            int bestPositive = 0;
            for (int s = 0; s < m;) {
                int e = s;
                while (e < m && group[e] == group[s]) e++;
                if (group[s] > 0) bestPositive = Math.max(bestPositive, e - s);
                s = e;
            }
            answer += m - bestPositive;
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := int(nextInt()), int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	// All k-window sums are equal iff a[i] == a[i + k]: each index class mod k must be constant.
	answer := 0
	group := make([]int64, 0, n)
	for start := 0; start < min(k, n); start++ {
		group = group[:0]
		for i := start; i < n; i += k {
			group = append(group, a[i])
		}
		slices.Sort(group)
		m := len(group)
		if group[0] == group[m-1] {
			continue // already constant: no change
		}
		// Otherwise the class becomes one positive value: keep its most frequent positive value.
		bestPositive := 0
		for s := 0; s < m; {
			e := s
			for e < m && group[e] == group[s] {
				e++
			}
			if group[s] > 0 {
				bestPositive = max(bestPositive, e-s)
			}
			s = e
		}
		answer += m - bestPositive
	}
	fmt.Println(answer)
}
